class Solution:
    def maxValue(self, n: int, restrictions: List[List[int]], diff: List[int]) -> int:
        INF = float('inf')
        cap = [INF] * n
        cap[0] = 0
        for idx, mv in restrictions:
            cap[idx] = min(cap[idx], mv)
        for i in range(1, n):
            cap[i] = min(cap[i], cap[i-1] + diff[i-1])
        for i in range(n - 2, -1, -1):
            cap[i] = min(cap[i], cap[i+1] + diff[i])
        return max(cap)

