class Solution {
public:
    int maxValue(int n, vector<vector<int>>& restrictions, vector<int>& diff) {
        const long long INF = LLONG_MAX;
        vector<long long> cap(n, INF);
        cap[0] = 0;
        for (auto& r : restrictions) cap[r[0]] = min(cap[r[0]], (long long)r[1]);
        for (int i = 1; i < n; i++) cap[i] = min(cap[i], cap[i-1] + diff[i-1]);
        for (int i = n - 2; i >= 0; i--) cap[i] = min(cap[i], cap[i+1] + diff[i]);
        return (int)*max_element(cap.begin(), cap.end());
    }
};

