class Solution {
    public int maxValue(int n, int[][] restrictions, int[] diff) {
        long INF = Long.MAX_VALUE;
        long[] cap = new long[n];
        java.util.Arrays.fill(cap, INF);
        cap[0] = 0;
        for (int[] r : restrictions) cap[r[0]] = Math.min(cap[r[0]], r[1]);
        for (int i = 1; i < n; i++) cap[i] = Math.min(cap[i], cap[i-1] + diff[i-1]);
        for (int i = n - 2; i >= 0; i--) cap[i] = Math.min(cap[i], cap[i+1] + diff[i]);
        long ans = 0;
        for (long c : cap) ans = Math.max(ans, c);
        return (int) ans;
    }
}

