class Solution:
    def maxValue(self, n: int, restrictions: List[List[int]], diff: List[int]) -> int:
        import itertools
        pts = sorted(restrictions + [[0, 0]])
        pre = [0]
        for d in diff:
            pre.append(pre[-1] + d)
        ans = 0
        for (i1, v1), (i2, v2) in zip(pts, pts[1:]):
            left = v1 + (pre[i2 - 1] - pre[i1 - 1] if i1 > 0 else pre[i2 - 1])
            right = v2 + (pre[i2 - 1] - pre[i1])
            ans = max(ans, min(left, right))
        return ans

