class Solution {
public:
    int maxValue(int n, vector<vector<int>>& restrictions, vector<int>& diff) {
        vector<vector<long long>> pts;
        for (auto& r : restrictions) pts.push_back({r[0], r[1]});
        pts.push_back({0, 0});
        sort(pts.begin(), pts.end());
        vector<long long> pre(n, 0);
        for (int i = 1; i < n; i++) pre[i] = pre[i-1] + diff[i-1];
        long long ans = 0;
        for (int k = 0; k + 1 < (int)pts.size(); k++) {
            long long i1 = pts[k][0], v1 = pts[k][1], i2 = pts[k+1][0], v2 = pts[k+1][1];
            long long left = v1 + pre[i2 - 1] - (i1 > 0 ? pre[i1 - 1] : 0);
            long long right = v2 + pre[i2 - 1] - pre[i1];
            ans = max(ans, min(left, right));
        }
        return (int)ans;
    }
};

