class Solution {
    public int maxValue(int n, int[][] restrictions, int[] diff) {
        long[][] pts = new long[restrictions.length + 1][];
        for (int i = 0; i < restrictions.length; i++)
            pts[i] = new long[]{restrictions[i][0], restrictions[i][1]};
        pts[restrictions.length] = new long[]{0, 0};
        java.util.Arrays.sort(pts, (a, b) -> Long.compare(a[0], b[0]));
        long[] pre = new long[n];
        for (int i = 1; i < n; i++) pre[i] = pre[i-1] + diff[i-1];
        long ans = 0;
        for (int k = 0; k + 1 < pts.length; k++) {
            long i1 = pts[k][0], v1 = pts[k][1], i2 = pts[k+1][0], v2 = pts[k+1][1];
            long left = v1 + pre[(int)i2 - 1] - (i1 > 0 ? pre[(int)i1 - 1] : 0);
            long right = v2 + pre[(int)i2 - 1] - pre[(int)i1];
            ans = Math.max(ans, Math.min(left, right));
        }
        return (int) ans;
    }
}

